from __future__ import annotations
import base64,zlib,subprocess,sys,json
from pathlib import Path
B64=''
raw=zlib.decompress(base64.b64decode(B64)).decode('utf-8').splitlines()
codes=[x for x in raw[1:] if x]
# Wave23 expects the old source only for race_code exclusion; create a minimal equivalent file.
Path('analysis_v289_3head_wave19_full_universe_payout_enriched.csv').write_text('race_code\n'+'\n'.join(codes)+'\n',encoding='utf-8')
if len(codes)!=678: raise RuntimeError(f'exclusion list count {len(codes)}')
subprocess.check_call([sys.executable,'research_v289_3head_wave23_fullpop_walkforward.py'])
print('WAVE23_RUNNER_OK exclusion=678')
